settings.custom_css:
/* ===== Venus single product (plugin Venus Product Page) ===== */
selector .pd-top>.e-con,selector .pd-tabs-sec{gap:0;--gap:0px;--padding-top:0px;--padding-right:0px;--padding-bottom:0px;--padding-left:0px;padding:0;min-width:0}
selector{width:calc(100% - 8vw);max-width:1240px;margin:0 auto;padding:24px 0 80px;gap:0;display:block;font-family:var(--e-global-typography-vnsbody-font-family),"Discovery Fs",system-ui,sans-serif;font-size:18px;font-weight:300;line-height:1.3;color:#141414}
selector .pd-crumbs{display:flex;flex-wrap:wrap;align-items:center;gap:8px;font-size:15px;color:rgba(20,20,20,.6)}
selector .pd-crumbs a{color:inherit;text-decoration:none}
selector .pd-crumbs a:hover{color:#3A4831;text-decoration:underline}
selector .pd-crumbs i{font-style:normal;opacity:.5}
selector .pd-crumbs span{color:#141414}
selector .pd-top{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:56px;margin-top:28px;align-items:start}
selector .pd-main{position:relative;aspect-ratio:4/5;border:1px solid rgba(20,20,20,.18);border-radius:12px;overflow:hidden;background:#FFFFFF}
selector .pd-main img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .35s ease}
selector .pd-main.is-zoom{cursor:zoom-in}
selector .pd-main.is-zoom img{transform:scale(1.8);transition:transform .15s ease-out}
selector .pd-badge{position:absolute;top:14px;right:14px;z-index:2;height:32px;padding:0 14px;border-radius:12px;background:#3A4831;color:#FFFFFF;font-size:16px;font-weight:500;display:flex;align-items:center}
selector .pd-thumbs{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:12px}
selector .pd-th{padding:0;aspect-ratio:1/1;border:1px solid rgba(20,20,20,.18);border-radius:10px;overflow:hidden;background:#FFFFFF;cursor:pointer;opacity:.75;transition:opacity .15s,border-color .15s}
selector .pd-th:hover{opacity:1}
selector .pd-th.is-on{opacity:1;border:2px solid #3A4831}
selector .pd-th img{display:block;width:100%;height:100%;object-fit:cover}
selector .pd-title{margin:0;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:46px;line-height:1.1;color:#141414}
selector .pd-short{margin:14px 0 0;font-size:20px;line-height:1.45}
selector .pd-price-row{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 14px;margin-top:22px}
selector .pd-price{font-size:44px;font-weight:500;line-height:1}
selector .pd-price-row .rec-old{font-size:22px}
selector .pd-save{padding:4px 12px;border-radius:999px;background:rgba(58,72,49,.1);color:#3A4831;font-size:15px;font-weight:500}
selector .pd-note{margin:12px 0 0;font-size:15px;color:rgba(20,20,20,.65)}
selector .pd-buy{display:flex;gap:12px;margin-top:28px}
selector .pd-qty{display:inline-flex;align-items:center;flex:none;height:56px;border:1px solid rgba(20,20,20,.18);border-radius:12px;overflow:hidden;background:#FFFFFF}
selector .pd-qty button{width:46px;height:100%;display:flex;align-items:center;justify-content:center;border:0;background:none;color:#141414;cursor:pointer;transition:background .15s}
selector .pd-qty button:hover{background:rgba(20,20,20,.06)}
selector .pd-qty svg{width:18px;height:18px}
selector .pd-q-in{width:44px;height:100%;border:0;background:transparent;text-align:center;font:inherit;font-size:19px;color:#141414;padding:0;-moz-appearance:textfield}
selector .pd-cta{box-sizing:border-box;flex:1;height:56px;display:flex;align-items:center;justify-content:center;gap:8px;padding:0 24px;border:0;border-radius:12px;background:#3A4831;color:#FFFFFF;font:inherit;font-size:19px;font-weight:500;cursor:pointer;transition:background .15s}
selector .pd-cta:hover{background:#2C3624}
selector .pd-cta-sum b{font-weight:500}
selector .pd-share{display:inline-flex;align-items:center;gap:8px;margin-top:18px;color:#3A4831;font-size:16px;font-weight:500;text-decoration:none}
selector .pd-share:hover{text-decoration:underline}
selector .pd-share svg{width:22px;height:22px}
selector .pd-perks{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:32px 0 0;padding:26px 0 0;list-style:none;border-top:1px solid rgba(20,20,20,.12)}
selector .pd-perks li{display:flex;flex-direction:column;align-items:center;gap:10px;text-align:center;font-size:14px;line-height:1.3}
selector .pd-perk-i{display:inline-flex;align-items:center;justify-content:center;width:58px;height:58px;border-radius:50%;border:1px solid rgba(20,20,20,.18);background:#FFFFFF;color:#3A4831}
selector .pd-perk-i svg{width:27px;height:27px}

selector .pd-h2{margin:0;text-align:center;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:38px;line-height:1.12;color:#141414}
selector .pd-sub{margin:8px 0 0;text-align:center;font-size:18px;color:rgba(20,20,20,.7)}

selector .pd-adds{margin-top:80px}
selector .pd-add-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:16px;margin-top:28px}
selector .pd-add-grid-3{grid-template-columns:repeat(3,1fr);max-width:760px;margin-inline:auto}
selector .pd-add{position:relative;display:flex;flex-direction:column;background:#FFFFFF;border:1px solid rgba(20,20,20,.18);border-radius:12px;overflow:hidden;cursor:pointer;transition:border-color .15s,box-shadow .15s}
selector .pd-add:hover{border-color:#3A4831}
selector .pd-add:has(.pd-add-in:checked){border-color:#3A4831;box-shadow:0 0 0 1px #3A4831}
selector .pd-add:has(.pd-add-in:focus-visible){outline:2px solid #3A4831;outline-offset:2px}
selector .pd-add-in{position:absolute;opacity:0;pointer-events:none}
selector .pd-add-img{display:block;aspect-ratio:1/1;background:#F3E3C8;overflow:hidden}
selector .pd-add-img img{display:block;width:100%;height:100%;object-fit:cover}
selector .pd-add-name{display:block;padding:12px 14px 0;font-size:16px;line-height:1.25;min-height:2.5em}
selector .pd-add-row{display:flex;align-items:center;justify-content:space-between;padding:8px 14px 14px}
selector .pd-add-price{font-size:17px;font-weight:500}
selector .pd-add-btn{position:relative;flex:none;width:32px;height:32px;border-radius:50%;border:1.5px solid #3A4831;transition:background .15s}
selector .pd-add-btn i{position:absolute;inset:0}
selector .pd-add-btn i::before,selector .pd-add-btn i::after{content:"";position:absolute;left:50%;top:50%;width:14px;height:2px;background:#3A4831;transform:translate(-50%,-50%)}
selector .pd-add-btn i::after{transform:translate(-50%,-50%) rotate(90deg)}
selector .pd-add:has(.pd-add-in:checked) .pd-add-btn{background:#3A4831}
selector .pd-add:has(.pd-add-in:checked) .pd-add-btn i::before{width:12px;height:6px;background:none;border:solid #FFFFFF;border-width:0 0 2px 2px;transform:translate(-50%,-65%) rotate(-45deg)}
selector .pd-add:has(.pd-add-in:checked) .pd-add-btn i::after{display:none}

selector .pd-tabs-sec{max-width:900px;margin:80px auto 0}
selector .pd-tabs{display:flex;justify-content:center;gap:36px;border-bottom:1px solid rgba(20,20,20,.18)}
selector .pd-tab{padding:14px 4px;margin-bottom:-1px;border:0;border-bottom:2px solid transparent;background:none;font:inherit;font-size:20px;color:rgba(20,20,20,.55);cursor:pointer;transition:color .15s}
selector .pd-tab:hover{color:#141414}
selector .pd-tab.is-on{color:#141414;font-weight:500;border-bottom-color:#141414}
selector .pd-panel{padding:30px 0 0;font-size:18px;line-height:1.65}
selector .pd-panel p{margin:0 0 14px}
selector .pd-panel h3{margin:26px 0 8px;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:22px;color:#141414}
selector .pd-panel h3:first-child{margin-top:0}
selector .pd-panel ul{margin:0;padding-inline-start:22px}
selector .pd-panel li{margin-bottom:8px}
selector .pd-panel a{color:#3A4831;font-weight:500}

selector .pd-promise{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:80px;padding:40px 32px;border-radius:12px;background:#3A4831;color:#FFFFFF;text-align:center}
selector .pd-pr{display:flex;flex-direction:column;align-items:center;gap:8px}
selector .pd-pr .pd-perk-i{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.3);color:#FFFBE9}
selector .pd-pr b{font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:22px}
selector .pd-pr span:last-child{font-size:16px;opacity:.85}

selector .pd-revs{margin-top:80px}
selector .pd-rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:28px}
selector .pd-rev{margin:0;padding:22px;background:#FFFFFF;border:1px solid rgba(20,20,20,.18);border-radius:12px}
selector .pd-rev-top{display:flex;align-items:center;gap:12px}
selector .pd-rev-av{flex:none;width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#FFFFFF;font-size:19px;font-weight:500}
selector .pd-rev b{display:block;font-size:17px;font-weight:500}
selector .pd-rev small{display:block;font-size:14px;color:rgba(20,20,20,.6)}
selector .pd-stars{margin-top:14px;color:#C9A24B;font-size:19px;letter-spacing:2px}
selector .pd-rev blockquote{margin:10px 0 0;font-size:16px;line-height:1.55;display:-webkit-box;-webkit-line-clamp:8;-webkit-box-orient:vertical;overflow:hidden}

selector .pd-faq{max-width:860px;margin:80px auto 0}
selector .pd-faq-l{margin-top:28px;border-top:1px solid rgba(20,20,20,.18)}
selector .pd-faq-i{border-bottom:1px solid rgba(20,20,20,.18)}
selector .pd-faq-q{box-sizing:border-box;width:100%;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:20px 4px;border:0;background:none;font:inherit;font-size:20px;text-align:start;color:#141414;cursor:pointer}
selector .pd-faq-q svg{flex:none;width:22px;height:22px;transition:transform .25s}
selector .pd-faq-q[aria-expanded="true"] svg{transform:rotate(180deg)}
selector .pd-faq-a p{margin:0 0 20px;padding-inline:4px;font-size:17px;line-height:1.65;color:rgba(20,20,20,.8)}

selector .pd-rel{margin-top:80px}

selector .pd-bar{position:fixed;left:0;right:0;bottom:0;z-index:40;padding:10px 4vw;background:#FFFBE9;border-top:1px solid rgba(20,20,20,.18);transform:translateY(110%);transition:transform .3s ease}
selector .pd-bar.is-on{transform:none}
selector .pd-bar-in{display:flex;align-items:center;justify-content:space-between;gap:16px;max-width:1240px;margin:0 auto}
selector .pd-bar-name{font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:20px}
selector .pd-cta-bar{flex:none;height:48px;padding:0 32px;font-size:18px}

@media(max-width:1024px){
  selector .pd-top{gap:32px}
  selector .pd-title{font-size:38px}
  selector .pd-add-grid{grid-template-columns:repeat(3,1fr)}
  selector .pd-perks{grid-template-columns:repeat(2,1fr);gap:20px}
  selector .pd-rev-grid{grid-template-columns:repeat(2,1fr)}
  selector .pd-rev-grid .pd-rev:nth-child(3){display:none}
}
@media(max-width:767px){
  selector{padding:16px 0 96px}
  selector .pd-crumbs{font-size:14px}
  selector .pd-top{grid-template-columns:1fr;gap:24px;margin-top:20px}
  selector .pd-title{font-size:32px}
  selector .pd-short{font-size:18px}
  selector .pd-price{font-size:38px}
  selector .pd-buy{margin-top:22px;gap:10px}
  selector .pd-qty button{width:40px}
  selector .pd-q-in{width:36px}
  selector .pd-buy .pd-cta{min-width:0;padding:0 12px;font-size:17px;white-space:nowrap}
  selector .pd-perks{grid-template-columns:repeat(4,1fr);gap:6px}
  selector .pd-perks li{font-size:12.5px}
  selector .pd-perk-i{width:52px;height:52px}
  selector .pd-h2{font-size:30px}
  selector .pd-sub{font-size:16px}
  selector .pd-adds,selector .pd-tabs-sec,selector .pd-promise,selector .pd-revs,selector .pd-faq,selector .pd-rel{margin-top:56px}
  selector .pd-add-grid,selector .pd-add-grid-3{grid-template-columns:repeat(2,1fr);gap:12px}
  selector .pd-add-name{font-size:15px;padding:10px 12px 0}
  selector .pd-add-row{padding:8px 12px 12px}
  selector .pd-tabs{gap:20px}
  selector .pd-tab{font-size:17px}
  selector .pd-panel{font-size:17px}
  selector .pd-promise{grid-template-columns:1fr;padding:32px 20px;gap:28px}
  selector .pd-rev-grid{grid-template-columns:1fr}
  selector .pd-rev-grid .pd-rev:nth-child(3){display:block}
  selector .pd-faq-q{font-size:18px}
  /* פס ההזמנה הצף תמיד בתחתית המסך */
  selector .pd-bar{transform:none;padding:10px 16px calc(10px + env(safe-area-inset-bottom,0px))}
  selector .pd-bar-name{display:none}
  selector .pd-cta-bar{width:100%;padding:0 20px}
}
@media(hover:none){selector .pd-main.is-zoom img{transform:none}}
selector .elementor-widget{margin:0}
selector .rec-old{font-size:16px;font-weight:300;color:rgba(20,20,20,.5);text-decoration:line-through;white-space:nowrap}
selector button{font-family:inherit;line-height:inherit;text-transform:none;letter-spacing:normal}
selector .pd-buy::before,selector .pd-buy::after{display:none}
selector :is(.pd-main,.pd-qty,.pd-perk-i,.pd-add-name,.pd-add-btn){box-sizing:content-box}
selector .pd-buy{margin-bottom:0}
selector .pd-panel>:last-child{margin-bottom:0}
selector .pd-rel{margin:80px 0 0}
@media(max-width:767px){selector .pd-rel{margin-top:56px}}
selector .pd-panel[hidden],selector .pd-faq-a[hidden]{display:none}
selector .woocommerce-notices-wrapper{margin:0}
